package dev.zomboid.gore;
import net.minecraft.world.entity.monster.Zombie;import net.minecraft.network.syncher.SynchedEntityData;import net.minecraft.nbt.CompoundTag;import com.tacz.guns.api.TimelessAPI;import traben.entity_model_features.models.animation.state.EMFState;import traben.entity_model_features.models.animation.math.variables.VariableRegistry;
public class FlowChecks {static int n;static void check(boolean b){n++;if(!b)throw new AssertionError("flow "+n);}public static class Bullet{public Object gunId;public int pierce;public Zombie.Point getDeltaMovement(){return new Zombie.Point(0,0,4);}Bullet(String type){gunId=type;TimelessAPI.entries.put(type,new TimelessAPI.Index(type));}}public record Hit(Object entity,Zombie.Point point){public Object getEntity(){return entity;}public Object getLocation(){return point;}public boolean isHeadshot(){return point.y>1.6;}}public record Source(Object attacker){public Object getDirectEntity(){return attacker;}public Object getEntity(){return attacker;}}public record Damage(Object entity,Source source,float amount){public Object getEntity(){return entity;}public Source getSource(){return source;}public float getNewDamage(){return amount;}}public static class Incoming {public Source source;public float amount=10;Incoming(Object z){source=new Source(z);}public Source getSource(){return source;}public float getAmount(){return amount;}public void setAmount(float a){amount=a;}}public record Tick(Object entity){public Object getEntity(){return entity;}}
 public static void main(String[]args){Gore.init();Zombie z=new Zombie();Gore.define(new SynchedEntityData.Builder(z.data));check(Gore.state(z)==0);Bullet pistol=new Bullet("pistol");Gore.begin(pistol,new Hit(z,new Zombie.Point(.4,1.3,0)));Gore.hurt(new Damage(z,new Source(pistol),3));Gore.end();check(z.pushes==1&&Math.abs(z.pushZ-.065)<.001&&z.hurtMarked);check((Gore.state(z)&4)==0&&(Gore.state(z)&(1<<10))!=0);Bullet shotgun=new Bullet("shotgun");Gore.begin(shotgun,new Hit(z,new Zombie.Point(.4,1.3,0)));Gore.hurt(new Damage(z,new Source(shotgun),6));Gore.end();check((Gore.state(z)&4)!=0);check(z.pushes==1);z.tickCount++;Gore.push(z,shotgun,Rules.Weapon.SHOTGUN);check(z.pushes==2&&Math.abs(z.pushZ-.185)<.001);Incoming attack=new Incoming(z);Gore.incoming(attack);check(Math.abs(attack.amount-6.5)<.01);Bullet sniper=new Bullet("sniper");Gore.pierce(sniper);check(sniper.pierce==2);Gore.begin(sniper,new Hit(z,new Zombie.Point(0,1.65,0)));Gore.hurt(new Damage(z,new Source(sniper),8));Gore.end();check(Gore.noJaw(z));Gore.begin(shotgun,new Hit(z,new Zombie.Point(.2,.3,0)));Gore.hurt(new Damage(z,new Source(shotgun),8));Gore.end();check(Rules.crawling(Gore.state(z))&&z.refresh>0);check(!z.speed.mods.isEmpty());CompoundTag saved=new CompoundTag();Gore.save(z,saved);Zombie copy=new Zombie();Gore.define(new SynchedEntityData.Builder(copy.data));Gore.restore(copy,saved);check(Gore.state(copy)==Gore.state(z));z.burning=true;for(int i=5;i<=120;i+=5){z.tickCount=i;Gore.tick(new Tick(z));}check(((Gore.state(z)>>>16)&3)==3);z.burning=false;int before=Gore.state(z);z.tickCount=125;Gore.tick(new Tick(z));check(Gore.state(z)==before);Gore.registerVisuals();EMFState.current=z;check(VariableRegistry.INSTANCE.vars.get("zg_burn").get()==3);check(VariableRegistry.INSTANCE.vars.get("zg_loss").get()==(Gore.state(z)&255));EMFState.current=null;check(VariableRegistry.INSTANCE.vars.get("zg_loss").get()==0);check(Gore.dimensions(z,new net.minecraft.world.entity.EntityDimensions(.6f,2)) instanceof net.minecraft.world.entity.EntityDimensions);System.out.println("Gore flow checks: "+n);}}
